<script setup lang="ts">import {computed} from 'vue';import PageHeading from '../components/common/PageHeading.vue';import Empty from '../components/common/Empty.vue';import AgreementSummary from '../components/AgreementSummary.vue';import VoteMatrix from '../components/VoteMatrix.vue';import CategoryMargins from '../components/CategoryMargins.vue';import RunList from '../components/RunList.vue';const p=defineProps<{studies:any[];specimens:any[];votes:any[];runs:any[];memos:any[]}>();defineEmits(['open']);const run=computed(()=>p.runs.find(r=>r.status==='completed'));</script><template><PageHeading index="01" title="在相同面板中，读一致与机会。" description="独立试样 → 固定三人逐票 → Fleiss κ → 整试样bootstrap → 分类口径复核"><a href="#config" class="primary">建立一致性研究 ↗</a></PageHeading><div class="inventory"><span>{{studies.length}}项研究 / {{specimens.length}}试样 / {{votes.length}}票</span><span>{{memos.filter(m=>m.status==='approved').length}}份复核说明已批准</span></div><template v-if="run"><div class="record-title"><small>LATEST COMPLETE / RUN {{run.id}}</small><h2>{{run.name}}</h2><button @click="$emit('open',run)">展开κ与全部重复 ↗</button></div><AgreementSummary :result="run.result"/><div class="atlas-layout"><VoteMatrix :result="run.result" :limit="12"/><CategoryMargins :result="run.result"/></div></template><Empty v-else title="第一份评议尚未完成" help="先核对每试样同一面板各一票，再建立一致性研究。"/><section class="section"><h2>研究归档</h2><RunList :runs="runs" @open="$emit('open',$event)"/></section></template>
